using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change: HasData no longer accepts mutable values like DateTime.UtcNow.
        // Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "VehicleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // For existing documents that already use "Discriminator", explicitly configure the old name.
        modelBuilder.Entity<Vehicle>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Car>("Car")
            .HasValue<Truck>("Truck");

        modelBuilder.Entity<Vehicle>().ToContainer("Vehicles");
        modelBuilder.Entity<Vehicle>().HasPartitionKey(v => v.PartitionKey);
    }

    // EF9 breaking change #2: Synchronous I/O on Cosmos DB is no longer supported.
    // All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
    public async Task<List<Vehicle>> GetVehiclesAsync()
    {
        // WRONG (throws in EF9): Vehicles.ToList()
        // CORRECT:
        return await Vehicles.ToListAsync();
    }

    public async Task<Vehicle?> GetVehicleByIdAsync(string id)
    {
        // WRONG (throws in EF9): Vehicles.FirstOrDefault(v => v.Id == id)
        // CORRECT:
        return await Vehicles.FirstOrDefaultAsync(v => v.Id == id);
    }
}

abstract class Vehicle
{
    public string Id { get; set; } = null!;
    public string PartitionKey { get; set; } = null!;
    public string Name { get; set; } = null!;
}
class Car : Vehicle { public int Seats { get; set; } }
class Truck : Vehicle { public double PayloadTons { get; set; } }

